package org.example.eshop.commerce;

import org.example.eshop.commerce.security.CommercePrincipal;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.*;
import org.springframework.web.context.WebApplicationContext;
import tools.jackson.databind.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;

@org.springframework.test.context.TestPropertySource(properties="commerce.jobs.enabled=false")
@SpringBootTest(classes=CommerceApplication.class,properties={"commerce.payments.bank.mode=DEMO","commerce.jobs.enabled=false"})
@ActiveProfiles("commerce")
@EnabledIfEnvironmentVariable(named="TV3_TEST_DB_URL",matches=".*furniture_shop_test_.*")
class AftercareIntegrationTest {
    @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("TV3_TEST_DB_URL"));r.add("spring.datasource.password",()->System.getenv("DB_PASSWORD"));r.add("spring.datasource.username",()->System.getenv().getOrDefault("DB_USERNAME","root"));}
    @Autowired JdbcTemplate db;
    @Autowired ObjectMapper mapper;
    @Autowired WebApplicationContext context;
    MockMvc mvc;
    final CommercePrincipal admin=new CommercePrincipal(101L,"admin","Admin",null,Set.of("ADMIN"));
    final CommercePrincipal customer=new CommercePrincipal(102L,"customer","Customer",null,Set.of("CUSTOMER"));
    final CommercePrincipal other=new CommercePrincipal(103L,"other","Other",null,Set.of("CUSTOMER"));
    final CommercePrincipal staff=new CommercePrincipal(104L,"staff","Staff",null,Set.of("STAFF"));
    @BeforeEach void setup(){
        assertTrue(db.queryForObject("SELECT DATABASE()",String.class).startsWith("furniture_shop_test_"));db.execute("DROP TRIGGER IF EXISTS tv3_payment_audit_fail");
        for(String t:List.of("audit_logs","refunds","return_items","return_requests","payment_events","payments","shipment_items","shipments","inventory_movements","inventory_reservations","coupon_redemptions","order_status_history","order_addresses","order_items","orders","cart_items","carts","coupons","user_addresses","inventory_balances","product_images","variant_materials","product_variants","products","categories","user_roles","users"))db.update("DELETE FROM "+t);
        for(var actor:List.of(admin,customer,other,staff)){db.update("INSERT INTO users(id,username,email,password_hash,full_name) VALUES(?,?,?,?,?)",actor.id(),actor.getUsername(),actor.getUsername()+"@example.invalid","unused",actor.getUsername());db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE code=?",actor.id(),actor.roles().iterator().next());}
        db.update("INSERT INTO categories(id,name,slug) VALUES(1001,'Sofa','payment-sofa')");db.update("INSERT INTO products(id,category_id,name,slug,status,assembly_required) VALUES(1001,1001,'Sofa payment','payment-sofa','ACTIVE',true)");db.update("INSERT INTO product_variants(id,product_id,sku,variant_key,name,price) VALUES(1001,1001,'PAY-KEM','cream','Kem',1000000)");db.update("INSERT INTO inventory_balances(warehouse_id,variant_id,on_hand_quantity) SELECT id,1001,50 FROM warehouses WHERE code='MAIN'");
        mvc=webAppContextSetup(context).apply(springSecurity()).build();
    }
    JsonNode json(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString(StandardCharsets.UTF_8));}
    long order(CommercePrincipal buyer,String method)throws Exception{return order(buyer,method,2,null);}
    long order(CommercePrincipal buyer,String method,int quantity,String coupon)throws Exception{
        var cart=json(mvc.perform(post("/api/cart/items").with(user(buyer)).with(csrf()).contentType("application/json").content("{\"variantId\":1001,\"quantity\":"+quantity+"}")).andExpect(status().isOk()).andReturn());
        var body=new LinkedHashMap<String,Object>();body.put("cartId",cart.get("id").asLong());body.put("paymentMethod",method);body.put("couponCode",coupon);body.put("assemblyRequested",true);body.put("shippingAddress",Map.of("recipientName",buyer.getUsername(),"phone","0901234567","addressLine1","12 Test","provinceName","Hồ Chí Minh","countryCode","VN"));
        var q=json(mvc.perform(post("/api/checkout/quote").with(user(buyer)).with(csrf()).contentType("application/json").content(mapper.writeValueAsString(body))).andExpect(status().isOk()).andReturn());body.put("quoteFingerprint",q.get("quoteFingerprint").asText());
        return json(mvc.perform(post("/api/checkout/orders").with(user(buyer)).with(csrf()).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(mapper.writeValueAsString(body))).andExpect(status().isCreated()).andReturn()).get("id").asLong();
    }
    long payment(long order){return db.queryForObject("SELECT id FROM payments WHERE order_id=? ORDER BY id DESC LIMIT 1",Long.class,order);}
    JsonNode summary(long order,CommercePrincipal actor,int expected)throws Exception{return json(mvc.perform(get("/api/orders/"+order+"/payments").with(user(actor))).andExpect(status().is(expected)).andReturn());}
    JsonNode confirm(long id,CommercePrincipal actor,String ref,String note,int expected)throws Exception{return json(mvc.perform(post("/api/admin/payments/"+id+"/confirm").with(user(actor)).with(csrf()).contentType("application/json").content(mapper.writeValueAsString(Map.of("reference",ref,"note",note,"acknowledged",true)))).andExpect(status().is(expected)).andReturn());}
    JsonNode create(long order,String method,String key,int expected)throws Exception{return json(mvc.perform(post("/api/orders/"+order+"/payments").with(user(customer)).with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(mapper.writeValueAsString(Map.of("method",method)))).andExpect(status().is(expected)).andReturn());}
    int count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
    void cancel(long order)throws Exception{mvc.perform(post("/api/orders/"+order+"/cancel").with(user(customer)).with(csrf()).contentType("application/json").content("{\"reason\":\"Đổi ý\"}")).andExpect(status().isOk());}
    @AfterEach void removeReturnFixtures(){db.execute("DROP TRIGGER IF EXISTS tv3_aftercare_audit_fail");db.update("DELETE FROM refunds WHERE return_request_id IS NOT NULL");db.update("DELETE FROM return_items");db.update("DELETE FROM return_requests");}
    long funded()throws Exception{long id=order(customer,"COD");confirm(payment(id),admin,"COLLECT-"+id,"",200);return id;}
    long cancelled()throws Exception{long id=funded();cancel(id);return id;}
    long refund(long order){return db.queryForObject("SELECT id FROM refunds WHERE order_id=? ORDER BY id DESC LIMIT 1",Long.class,order);}
    JsonNode refunds(long order)throws Exception{return json(mvc.perform(get("/api/admin/orders/"+order+"/refunds").with(user(admin))).andExpect(status().isOk()).andReturn());}
    JsonNode requestRefund(long order,long payment,String amount,String reason,Long returned,String key,int status)throws Exception{var body=new LinkedHashMap<String,Object>();body.put("paymentId",payment);body.put("amount",amount);body.put("reason",reason);body.put("returnRequestId",returned);return json(mvc.perform(post("/api/admin/orders/"+order+"/refunds").with(user(admin)).with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(mapper.writeValueAsString(body))).andExpect(status().is(status)).andReturn());}
    JsonNode settle(long id,CommercePrincipal actor,String ref,String note,int status)throws Exception{return json(mvc.perform(post("/api/admin/refunds/"+id+"/confirm").with(user(actor)).with(csrf()).contentType("application/json").content(mapper.writeValueAsString(Map.of("reference",ref,"note",note,"acknowledged",true)))).andExpect(status().is(status)).andReturn());}
    JsonNode voidRefund(long id,String reason,int status)throws Exception{return json(mvc.perform(post("/api/admin/refunds/"+id+"/cancel").with(user(admin)).with(csrf()).contentType("application/json").content(mapper.writeValueAsString(Map.of("reason",reason,"acknowledged",true)))).andExpect(status().is(status)).andReturn());}
    long warehouse(){return db.queryForObject("SELECT id FROM warehouses WHERE code='MAIN'",Long.class);}
    long item(long order){return db.queryForObject("SELECT id FROM order_items WHERE order_id=?",Long.class,order);}
    JsonNode postAs(String path,CommercePrincipal actor,Object body,int expected)throws Exception{return json(mvc.perform(post(path).with(user(actor)).with(csrf()).contentType("application/json").content(mapper.writeValueAsString(body))).andExpect(status().is(expected)).andReturn());}
    long dispatch(long order)throws Exception{return json(mvc.perform(post("/api/admin/inventory/orders/"+order+"/dispatch").with(user(staff)).with(csrf()).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(mapper.writeValueAsString(Map.of("warehouseId",warehouse(),"carrier","TEST","trackingNumber","AFTER-"+order)))).andExpect(status().isOk()).andReturn()).get("shipmentId").asLong();}
    void deliver(long shipment)throws Exception{mvc.perform(post("/api/admin/inventory/shipments/"+shipment+"/status").with(user(staff)).with(csrf()).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content("{\"targetStatus\":\"DELIVERED\",\"reason\":\"Actual recipient handover\"}")).andExpect(status().isOk());}
    long delivered()throws Exception{long id=order(customer,"COD");long s=dispatch(id);deliver(s);confirm(payment(id),staff,"ACTUAL-COLLECT-"+id,"",200);return id;}
    JsonNode aftercare(long order,boolean adminView)throws Exception{return json(mvc.perform(get(adminView?"/api/admin/aftercare/orders/"+order:"/api/orders/"+order+"/returns").with(user(adminView?staff:customer))).andExpect(status().isOk()).andReturn());}
    JsonNode returns(long order,int quantity,String reason,String key,int expected)throws Exception{return json(mvc.perform(post("/api/orders/"+order+"/returns").with(user(customer)).with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(mapper.writeValueAsString(Map.of("reason",reason,"items",List.of(Map.of("orderItemId",item(order),"quantity",quantity)))))).andExpect(status().is(expected)).andReturn());}
    long request(long order)throws Exception{return returns(order,2,"Customer public reason","aftercare-request-key",201).get("selectedReturnId").asLong();}
    JsonNode decide(long returned,CommercePrincipal actor,String decision,String reason,int code)throws Exception{return postAs("/api/admin/aftercare/returns/"+returned+"/decision",actor,Map.of("decision",decision,"reason",reason),code);}
    Object receipt(long returned,int received,int restock){long line=db.queryForObject("SELECT id FROM return_items WHERE return_request_id=?",Long.class,returned);return Map.of("warehouseId",warehouse(),"acknowledged",true,"items",List.of(Map.of("returnItemId",line,"receivedQuantity",received,"restockQuantity",restock,"conditionNote","Private inspection")));}
    JsonNode receive(long returned,Object body,int code)throws Exception{return postAs("/api/admin/aftercare/returns/"+returned+"/receive",staff,body,code);}
    @Test void deliveredOnlyOwnerCsrfAndRequestIntentReplay()throws Exception{
        long id=order(customer,"COD");mvc.perform(get("/api/orders/"+id+"/returns").with(user(other))).andExpect(status().isNotFound());mvc.perform(get("/api/admin/aftercare/orders/"+id).with(user(customer))).andExpect(status().isForbidden());mvc.perform(post("/api/orders/"+id+"/returns").with(user(customer)).contentType("application/json").content("{}")).andExpect(status().isForbidden());returns(id,1,"No delivery yet","before-delivery-key",409);long s=dispatch(id);deliver(s);var a=returns(id,2,"Customer public reason","request-exact-key",201);long r=a.get("selectedReturnId").asLong();decide(r,staff,"APPROVE","Private approval",200);assertEquals(r,returns(id,2,"Customer public reason","request-exact-key",201).get("selectedReturnId").asLong());assertEquals("IDEMPOTENCY_CONFLICT",returns(id,1,"Customer public reason","request-exact-key",409).get("code").asText());assertEquals("RETURN_QUANTITY_EXCEEDED",returns(id,1,"Overlap","different-request-key",409).get("code").asText());assertEquals(0,count("refunds"));assertEquals(48,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));
    }
    @Test void realDeliveryInstallationReceiptAndRefundKeepEvidenceAndPrivacy()throws Exception{
        long id=delivered(),s=db.queryForObject("SELECT id FROM shipments WHERE order_id=?",Long.class,id);var proof=Map.of("reference","INSTALL-PROOF-001","note","Private installation","acknowledged",true);assertEquals("COMPLETED",postAs("/api/admin/aftercare/shipments/"+s+"/installation",staff,proof,200).get("orderStatus").asText());var first=db.queryForMap("SELECT installation_completed_at,installation_staff_id FROM shipments WHERE id=?",s);postAs("/api/admin/aftercare/shipments/"+s+"/installation",admin,proof,200);assertEquals(first,db.queryForMap("SELECT installation_completed_at,installation_staff_id FROM shipments WHERE id=?",s));postAs("/api/admin/aftercare/shipments/"+s+"/installation",admin,Map.of("reference","OTHER-PROOF","acknowledged",true),409);long r=request(id);decide(r,staff,"APPROVE","Private approval",200);decide(r,admin,"APPROVE","Private approval",200);assertEquals(104L,db.queryForObject("SELECT approved_by FROM return_requests WHERE id=?",Long.class,r));decide(r,admin,"REJECT","Conflicting",409);requestRefund(id,payment(id),"1","Not received",r,"before-receipt-key",409);receive(r,receipt(r,1,1),200);receive(r,receipt(r,1,1),200);assertEquals("RETURN_RECEIPT_CONFLICT",receive(r,receipt(r,2,1),409).get("code").asText());assertEquals(49,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));assertEquals(0,db.queryForObject("SELECT reserved_quantity FROM inventory_balances",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM inventory_movements WHERE movement_type='RETURN'",Integer.class));assertEquals("DELIVERED",db.queryForObject("SELECT status FROM shipments WHERE id=?",String.class,s));assertEquals("COMPLETED",db.queryForObject("SELECT status FROM orders WHERE id=?",String.class,id));var visible=aftercare(id,false).toString();assertFalse(visible.contains("Private"));assertFalse(visible.contains("approvedBy"));assertFalse(visible.contains("staffNote"));requestRefund(id,payment(id),"1000000","Actually received goods",r,"actual-return-refund-key",201);requestRefund(id,payment(id),"1","Exceeds received goods",r,"exceed-return-refund-key",409);settle(refund(id),admin,"ACTUAL-RETURN-REFUND","",200);assertEquals(49,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));
    }
    @Test void rejectionReleasesClaimAndConcurrentNewRequestsCannotOverlap()throws Exception{
        long id=delivered(),r=request(id);decide(r,staff,"REJECT","Not eligible",200);assertEquals(2,aftercare(id,false).get("items").get(0).get("returnableQuantity").asInt());var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return returnStatus(id,"concurrent-return-a");});var b=pool.submit(()->{start.await();return returnStatus(id,"concurrent-return-b");});start.countDown();var results=new ArrayList<>(List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS)));Collections.sort(results);assertEquals(List.of(201,409),results);}finally{pool.shutdownNow();}
    }
    int returnStatus(long id,String key)throws Exception{return mvc.perform(post("/api/orders/"+id+"/returns").with(user(customer)).with(csrf()).header("Idempotency-Key",key).contentType("application/json").content(mapper.writeValueAsString(Map.of("reason","Race","items",List.of(Map.of("orderItemId",item(id),"quantity",2)))))).andReturn().getResponse().getStatus();}
    @Test void receiptAuditFailureRollsBackStockAndReceiptAndRejectsInvalidQuantities()throws Exception{
        long id=delivered(),r=request(id);decide(r,staff,"APPROVE","Approved privately",200);receive(r,receipt(r,1,2),400);receive(r,receipt(r,0,0),400);db.execute("CREATE TRIGGER tv3_aftercare_audit_fail BEFORE INSERT ON audit_logs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='forced aftercare audit failure'");try{assertThrows(Exception.class,()->receive(r,receipt(r,1,1),200));}finally{db.execute("DROP TRIGGER tv3_aftercare_audit_fail");}assertEquals("APPROVED",db.queryForObject("SELECT status FROM return_requests WHERE id=?",String.class,r));assertEquals(0,db.queryForObject("SELECT received_quantity FROM return_items WHERE return_request_id=?",Integer.class,r));assertEquals(48,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM inventory_movements WHERE movement_type='RETURN'",Integer.class));
    }
    @Test void installationRequiresDeliveredSelectedServiceAndExplicitProof()throws Exception{
        long id=order(customer,"COD"),s=dispatch(id);postAs("/api/admin/aftercare/shipments/"+s+"/installation",staff,Map.of("reference","INSTALL-EARLY","acknowledged",true),409);deliver(s);postAs("/api/admin/aftercare/shipments/"+s+"/installation",staff,Map.of("reference","INSTALL-LATE"),400);postAs("/api/admin/aftercare/shipments/"+s+"/installation",staff,Map.of("reference","INSTALL-LATE","acknowledged",true),200);assertEquals("PROCESSING",db.queryForObject("SELECT status FROM orders WHERE id=?",String.class,id));confirm(payment(id),staff,"COLLECT-AFTER-INSTALL","",200);assertEquals("COMPLETED",db.queryForObject("SELECT status FROM orders WHERE id=?",String.class,id));
    }
    @Test void duplicateReceiptRaceRestocksOnceAndMalformedLinesCannotMutate()throws Exception{
        long id=delivered(),r=request(id);decide(r,staff,"APPROVE","Approved",200);postAs("/api/admin/aftercare/returns/"+r+"/receive",customer,receipt(r,1,1),403);postAs("/api/admin/aftercare/returns/"+r+"/receive",staff,Map.of("warehouseId",warehouse(),"acknowledged",true,"items",List.of()),400);var body=receipt(r,1,0);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return receive(r,body,200);});var b=pool.submit(()->{start.await();return receive(r,body,200);});start.countDown();a.get(20,TimeUnit.SECONDS);b.get(20,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertEquals(48,db.queryForObject("SELECT on_hand_quantity FROM inventory_balances",Integer.class));assertEquals(1,db.queryForObject("SELECT received_quantity FROM return_items WHERE return_request_id=?",Integer.class,r));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM inventory_movements WHERE movement_type='RETURN'",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM audit_logs WHERE action='RETURN_RECEIVED'",Integer.class));
    }
}
